terraform {
  required_version = ">=1.11"

  required_providers {
    zia = {
      source = "zscaler/zia"
      version = "4.4.8"
    }
  }
}

locals {
  zia_end_user_notification = {
    test = {
      to_email = "testuncatrequest@example.local"
      cc_email = ""
      zscloud = "zscloud.net"
    }
    prod = {
      to_email = "uncatrequest@example.local"
      cc_email = ""
      zscloud = "zscalertwo.net"
    }
  }
}

resource "zia_end_user_notification" "this" {
  //notification
  notification_type              = "DEFAULT"
  display_reason                 = true
  display_comp_name              = true
  display_comp_logo              = true

  //default global block page
  custom_text = chomp(<<-EOT
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Selection Panel with Dropdowns and Buttons</title>
  <style>
  :is(h1, h2, h3, h4, h5, h6, p) {
    text-align: center;
  }
  .text-red { /* matches zscaler red Sorry message and border */
    color: #fd4239 !important;
    font-weight: bold;
  }
  .hidden {
    display: none;
  }
  /* Style the outer container (replacing form) */
  .selection-panel {
    margin: 0 auto;
    padding: 20px;
    display: flex;
    flex-direction: column;
  }
  /* Each field wrapper for vertical stacking */
  .form-field {
    margin-bottom: 20px;
  }
  /* Labels as blocks above dropdowns */
  label {
    display: block;
    margin-bottom: 8px;
    font-weight: bold;
  }
  /* Set all dropdowns to the same fixed width */
  select {
    width: 100%;
    padding: 10px;
    border: 1px solid #ccc;
    border-radius: 4px;
    box-sizing: border-box;
  }
  /* Style the textarea to match the dropdowns */
  textarea {
    width: 100%;
    padding: 10px;
    border: 1px solid #ccc;
    border-radius: 4px;
    box-sizing: border-box;
    resize: vertical;
  }
  /* center class for re-use */
  .center {
    display: block;
    margin-left: auto;
    margin-right: auto;
    width: 50%;
  }
  /* Container for buttons at the bottom */
  .button-container {
    display: flex;
    justify-content: space-between;
    margin-top: auto;
  }
  /* Style all the buttons */
  button {
    padding: 10px 20px; /* Adjust padding for better fit */
    background-color: #000000;
    border: none;
    border-radius: 4px;
    /* color: #fff; */
    cursor: pointer;
  }
  #submitBtn {
    background-color: #000000;
    color: white;
  }
  #submitBtn:hover {
    background-color: #5a6268;
  }
  #helpBtn {
    background-color: #000000;
    color: white;
  }
  #helpBtn:hover {
    background-color: #5a6268;
  }
  </style>
</head>
<body>
  <div class="container">
    <h1>WARNING!!!</h1>


      <div id="defaultBlockPageDiv" class="default-content show">
        <h2>Access to this website is restricted</h2>
        <h3>This website you are attempting to access contains content that is not in compliance with the company standards <a href="https://example.com">End User Acceptable Use Standard</a></h2>
      </div>


      <div id="uncatMiscRequestForm" class="alternative-content hidden">
        <h2>If you require access for business purposes, please select from the menus below and click submit. This will launch your Outlook client to send the request.</h2>
        <br>
        <div class="selection-panel" role="form">
        <div class="form-field">
          <label for="justification"><span class="text-red">*</span> Choose a Justification:</label>
          <select id="justification" required>
            <option value="">Select a justification...</option>
            <option value="Direct Work Requirement">Direct Work Requirement</option>
            <option value="Client/Vendor Collaboration">Client/Vendor Collaboration</option>
            <option value="Risk Assessment">Risk Assessment</option>
            <option value="Documentation Purposes">Documentation Purposes</option>
            <option value="Testing and Development">Testing and Development</option>
            <option value="Research/Market Data">Research/Market Data</option>
            <option value="New Vendor Relationship">New Vendor Relationship</option>
            <option value="Other Needs">Other Needs (Please fill description in COMMENTS)</option>
          </select>
        </div>
        <div class="form-field">
          <label for="zscalerUrlCategory"><span class="text-red">*</span> Zscaler URL Category:</label>
          <select id="zscalerUrlCategory" required>
            <option value="">Select a potential URL category...</option>
            <option value="Business Services">Business Services</option>
            <option value="Financial Services">Financial Services</option>
            <option value="Health">Health</option>
            <option value="Legal">Legal</option>
            <option value="Shopping">Shopping</option>
            <option value="Email">Email</option>
            <option value="Instant Messaging">Instant Messaging</option>
            <option value="Social Networking">Social Networking</option>
            <option value="Web Chat">Web Chat</option>
            <option value="Educational Institutions">Educational Institutions</option>
            <option value="Educational Materials">Educational Materials</option>
            <option value="Games">Games</option>
            <option value="Music">Music</option>
            <option value="Streaming Media">Streaming Media</option>
            <option value="Sports">Sports</option>
            <option value="News">News</option>
            <option value="Blogs & Forums">Blogs & Forums</option>
            <option value="Reference">Reference</option>
            <option value="Search Engines & Portals">Search Engines & Portals</option>
            <option value="Computers & Internet">Computers & Internet</option>
            <option value="General AI and ML Applications">General AI and ML Applications</option>
            <option value="Information Technology">Information Technology</option>
            <option value="Travel">Travel</option>
            <option value="Transportation">Transportation</option>
            <option value="Personal Sites">Personal Sites</option>
            <option value="Religion">Religion</option>
            <option value="Society">Society</option>
            <option value="Miscellaneous">Miscellaneous</option>
          </select>
        </div>

        <div class="form-field">
          <label for="comments">Additional Comments (Optional):</label>
          <textarea id="comments" name="comments" maxlength="1024" placeholder="Enter any additional justification or comments here for manager approval..." rows="4"></textarea>
        </div>

        <div class="button-container">
          <button id="submitBtn" type="button">Submit</button>
          <button id="helpBtn" type="button">Help</button>
        </div>
      </div>
  </div>
  <div id="footer">
      <h5>Thank You For Your Cooperation</h5>
    </div>

  <script>
    // These are the 4 categories we currently need to detect and allow requests via xsoar as of August 2025
    const zscalerCategoriesForAutomation = [
      'miscellaneous or unknown',
      'newly registered and observed domains',
      'non categorizable',
      'other miscellaneous',
    ]

    // Function to check for target TD elements, lowercase to ensure case insensitive search
    function checkForTargetCell() {
      const rsnTds = document.querySelectorAll('td.eu_co.rsn');
      const targetByContent = Array.from(rsnTds).find(td => {
        const cellText = td.textContent.trim().toLowerCase();
        return zscalerCategoriesForAutomation.some(targetString =>
          cellText.includes(targetString)
        );
      });

      // Backup method: Check for TD with specific class
      const targetByClass = document.querySelector(`td.target-section`);
      const targetFound = targetByContent || targetByClass;
      if (targetFound) {
        showUncatMiscRequestForm();
        return true;
      } else {
        showDefaultBlockPage();
        return false;
      }
    }

    // References to the div elements
    const defaultBlockPageDiv = document.getElementById('defaultBlockPageDiv');
    const uncatMiscRequestForm = document.getElementById('uncatMiscRequestForm');

    // Function to show default content
    function showDefaultBlockPage() {
      defaultBlockPageDiv.classList.remove('hidden');
      uncatMiscRequestForm.classList.add('hidden');
    }
    // Function to show alternative content
    function showUncatMiscRequestForm() {
      defaultBlockPageDiv.classList.add('hidden');
      uncatMiscRequestForm.classList.remove('hidden');
    }

    // Function for Submit button: Create email with form values
    document.getElementById('submitBtn').addEventListener('click', function() {
      const toEmail = "${local.zia_end_user_notification[var.environment].to_email}";
      const ccEmail = ""
      const url = window.location.origin.replace(/\./g, '[.]');
      const dd1 = document.getElementById('justification');
      const dd2 = document.getElementById('zscalerUrlCategory');
      const dd3 = document.getElementById('comments');
      const subject = encodeURIComponent(`Site Unblock Request - $${url}`);

      function updateMailtoLink() {
        const jsonData = {
          environment: "${var.environment} - ${local.zia_end_user_notification[var.environment].zscloud}",
          url: `$${url}`,
          timestamp: new Date().toLocaleString(),
          useragent: navigator.userAgent,
          justification: dd1.value,
          zscaler_category: dd2.value,
          comments: dd3.value.trim(),
        };
        let body = `%0A ------------------------------------------------------------------------------ %0A ALTERING TEXT BELOW THIS LINE WILL CANCEL REQUEST! %0A%0A $${encodeURIComponent(JSON.stringify(jsonData, null, 2))} %0A%0A  ------------------------------------------------------------------------------ %0A ALTERING TEXT ABOVE THIS LINE WILL CANCEL REQUEST! %0A `;
        window.location.href = `mailto:$${toEmail}?cc=$${ccEmail}&subject=$${subject}&body=$${body}`;
        let email = `mailto:$${toEmail}?cc=$${ccEmail}&subject=$${subject}&body=$${body}`;
      }

      updateMailtoLink();
    });

    // Function for HELP button: Open new window with how-to
    document.getElementById('helpBtn').addEventListener('click', function() {
      window.open("https://example.com/", "_blank");
    });

  </script>
</body>
</html>
EOT
